begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) select ('51900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'meetup-profile-'||n||'@example.invalid' from generate_series(1,5) n;
insert into public.profiles(id,nickname,city_id,terms_accepted_at,privacy_accepted_at,ai_safety_consent_at,consent_version)
select id,'General secret '||right(id::text,1),'vancouver',now(),now(),now(),'test' from auth.users where id::text like '51900000-%';
select set_config('request.jwt.claims','{"sub":"51900000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.save_chilling_profile('{"version":2,"displayName":"Meetup host","cityId":"vancouver","photoPaths":[],"publicPhotoPath":null,"intro":"Host introduction","interests":["walk"],"promptOne":"Private host answer","promptTwo":"Another host answer","promptOneId":"meet","promptTwoId":"join","shareWithMembers":false,"preferences":{"activities":["walk"],"availability":"Owner secret","pace":"relaxed"}}')$$,'v2 saves independent identity');
select is(public.get_my_chilling_profile()->>'displayName','Meetup host','owner sees meetup name');
select lives_ok($$select public.save_chilling_profile('{"intro":"Old client","interests":["walk"],"promptOne":"a","promptTwo":"b"}')$$,'old client keeps original text editing after v2 upgrade');
select is(public.get_my_chilling_profile()->>'displayName','Meetup host','legacy edit preserves v2 identity');
select is(public.get_my_chilling_profile()->'preferences'->>'availability','Owner secret','legacy edit preserves private preferences');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"cityId":"unknown-city"}')$$,'P0001','INVALID_CHILLING_PROFILE','unknown city rejected');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"shareWithMembers":"true"}')$$,'P0001','INVALID_CHILLING_PROFILE','sharing consent must be boolean');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"photoPaths":["51900000-0000-4000-8000-000000000001/../avatar.webp"]}')$$,'P0001','INVALID_CHILLING_PHOTO','path traversal rejected');

select is(public.get_my_chilling_profile()->'preferences'->>'availability','Owner secret','owner sees private preferences');
select is((select nickname::text from public.profiles where id=auth.uid()),'General secret 1','save never changes general identity');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"unexpected":true}')$$,'P0001','INVALID_CHILLING_PROFILE','unknown profile fields rejected');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"promptOneId":"unknown"}')$$,'P0001','INVALID_CHILLING_PROFILE','unknown prompt IDs rejected');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"preferences":{"availability":"x","pace":"fast","activities":[]}}')$$,'P0001','INVALID_CHILLING_PROFILE','preference allowlist enforced');
reset role;
insert into storage.objects(bucket_id,name,owner_id,metadata) values
('meetup-profiles','51900000-0000-4000-8000-000000000001/1792380000000-aabbccdd.webp','51900000-0000-4000-8000-000000000001','{"size":1024,"mimetype":"image/webp"}'),
('meetup-profiles','51900000-0000-4000-8000-000000000002/1792380000000-aabbccdd.webp','51900000-0000-4000-8000-000000000002','{"size":1024,"mimetype":"image/webp"}'),
('meetup-profiles','51900000-0000-4000-8000-000000000003/1792380000000-aabbccdd.webp','51900000-0000-4000-8000-000000000003','{"size":1024,"mimetype":"image/webp"}');
set local role authenticated;
select lives_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"photoPaths":["51900000-0000-4000-8000-000000000001/1792380000000-aabbccdd.webp"],"publicPhotoPath":"51900000-0000-4000-8000-000000000001/1792380000000-aabbccdd.webp"}')$$,'owner selects an owned private photo');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"photoPaths":["51900000-0000-4000-8000-000000000002/1792380000000-aabbccdd.webp"]}')$$,'P0001','INVALID_CHILLING_PHOTO','foreign photo rejected');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"publicPhotoPath":"51900000-0000-4000-8000-000000000001/1792380000000-deadbeef.webp"}')$$,'P0001','INVALID_CHILLING_PHOTO','public photo must be selected');
reset role;
insert into storage.objects(bucket_id,name,owner_id,metadata)
select 'meetup-profiles','51900000-0000-4000-8000-000000000001/1792380000000-'||suffix||'.webp','51900000-0000-4000-8000-000000000001','{"size":1024,"mimetype":"image/webp"}'::jsonb
from unnest(array['1010101a','1010101b','1010101c']) suffix;
set local role authenticated;
select lives_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"photoPaths":["51900000-0000-4000-8000-000000000001/1792380000000-aabbccdd.webp","51900000-0000-4000-8000-000000000001/1792380000000-1010101a.webp","51900000-0000-4000-8000-000000000001/1792380000000-1010101b.webp"]}')$$,'three unique owned photos are valid');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"photoPaths":["51900000-0000-4000-8000-000000000001/1792380000000-aabbccdd.webp","51900000-0000-4000-8000-000000000001/1792380000000-1010101a.webp","51900000-0000-4000-8000-000000000001/1792380000000-1010101b.webp","51900000-0000-4000-8000-000000000001/1792380000000-1010101c.webp"]}')$$,'P0001','INVALID_CHILLING_PHOTO','four valid owned photos exceed the profile bound');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"photoPaths":["51900000-0000-4000-8000-000000000001/1792380000000-aabbccdd.webp","51900000-0000-4000-8000-000000000001/1792380000000-aabbccdd.webp"]}')$$,'P0001','INVALID_CHILLING_PHOTO','duplicate owned photos are rejected');
select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"photoPaths":["51900000-0000-4000-8000-000000000001/1792380000000-aabbccdd.webp"]}');
select set_config('storage.operation','storage.object.delete',true);
select set_config('storage.allow_delete_query','true',true);
delete from storage.objects where bucket_id='meetup-profiles' and name like '%1010101_.webp';

select lives_ok($$select public.save_chilling_profile('{"intro":"Legacy photo-safe edit","interests":["walk"],"promptOne":"Old one","promptTwo":"Old two"}')$$,'legacy text edit preserves saved private photos');
select is(public.get_my_chilling_profile()->'photoPaths'->>0,'51900000-0000-4000-8000-000000000001/1792380000000-aabbccdd.webp','legacy save does not discard v2 photo paths');
select is(public.get_my_chilling_profile()->>'promptOneId','meet','legacy first answer retains its original question label');
select is(public.get_my_chilling_profile()->>'promptTwoId','join','legacy second answer retains its original question label');
select set_config('test.compat_post',public.create_chilling_event('vancouver','Old client host consent','Synthetic meetup','{"eventKind":"group","cadence":"weekly","capacity":3}','Question?')::text,true);
select ok(not(public.get_chilling_host_profile(current_setting('test.compat_post')::uuid) ?| array['version','displayName','cityId','photoPaths','publicPhotoPath','preferences','revision']),'legacy host publication after v2 upgrade exposes only original text scope');
select is(public.get_chilling_host_profile(current_setting('test.compat_post')::uuid)->>'promptOne','Old one','legacy hosting text still works after v2 upgrade');
select set_config('test.host_revision',public.get_my_chilling_profile()->>'revision',true);
select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"intro":"Host edited after preview"}');
select throws_ok($$select public.create_chilling_event('vancouver','Stale host preview','Synthetic meetup','{"eventKind":"group","cadence":"weekly","capacity":3,"hostProfileConsentVersion":"chilling-v2"}'::jsonb||jsonb_build_object('hostProfileRevision',current_setting('test.host_revision')),'Question?')$$,'P0001','CHILLING_PROFILE_CHANGED','host publication rejects a stale preview revision');
select is((select count(*)::integer from public.posts where author_id=auth.uid() and title='Stale host preview'),0,'stale host preview creates no partial post');
select set_config('test.profile_post',public.create_chilling_event('vancouver','Synthetic profile meetup','Synthetic meetup','{"eventKind":"group","cadence":"weekly","capacity":3,"hostProfileConsentVersion":"chilling-v2"}'::jsonb||jsonb_build_object('hostProfileRevision',public.get_my_chilling_profile()->>'revision'),'Question?')::text,true);
reset role;
select set_config('request.jwt.claims','{"sub":"51900000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.save_chilling_profile('{"version":2,"displayName":"Snapshot name","cityId":"vancouver","photoPaths":["51900000-0000-4000-8000-000000000002/1792380000000-aabbccdd.webp"],"publicPhotoPath":null,"intro":"Applicant intro","interests":["walk"],"promptOne":"Private one","promptTwo":"Private two","promptOneId":"weekend","promptTwoId":"learn","shareWithMembers":true,"preferences":{"activities":[],"availability":"Private availability","pace":"any"}}')$$,'applicant saves separate identity');
select throws_ok($$select public.request_chilling_join(current_setting('test.profile_post')::uuid,'Private application answer','wrong')$$,'P0001','CHILLING_CONSENT_REQUIRED','unknown consent version is denied');
select throws_ok($$select public.request_chilling_join(current_setting('test.profile_post')::uuid,'Unbound preview','chilling-v2')$$,'P0001','CHILLING_PROFILE_CHANGED','legacy route cannot bypass v2 preview revision');
select set_config('test.applicant_revision',public.get_my_chilling_profile()->>'revision',true);
select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"intro":"Applicant edited after preview"}');
select throws_ok($$select public.request_chilling_join_v2(current_setting('test.profile_post')::uuid,'Stale preview answer','chilling-v2',current_setting('test.applicant_revision'))$$,'P0001','CHILLING_PROFILE_CHANGED','application rejects a stale preview revision');
select is((select count(*)::integer from public.meetup_requests where post_id=current_setting('test.profile_post')::uuid and requester_id=auth.uid()),0,'stale application preview creates no request or snapshot');
select set_config('test.profile_request',public.request_chilling_join_v2(current_setting('test.profile_post')::uuid,'Private application answer','chilling-v2',public.get_my_chilling_profile()->>'revision')::text,true);
select ok(not (public.get_chilling_application(current_setting('test.profile_request')::uuid)->'profile' ? 'preferences'),'application never stores owner preferences');
select ok(not (public.get_chilling_application(current_setting('test.profile_request')::uuid)->'profile' ? 'revision'),'owner revision is not stored in application snapshot');
select ok(not (public.get_chilling_host_profile(current_setting('test.profile_post')::uuid) ? 'revision'),'owner revision is not public host metadata');

select lives_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"displayName":"Later name","intro":"Later intro"}')$$,'owner edits current profile');
select is(public.get_chilling_application(current_setting('test.profile_request')::uuid)->'profile'->>'displayName','Snapshot name','application identity is immutable');
select is(public.get_chilling_member_profile(current_setting('test.profile_post')::uuid,'51900000-0000-4000-8000-000000000002')->>'displayName','Snapshot name','own meetup profile uses request snapshot');
select is(public.get_chilling_host_profile(current_setting('test.profile_post')::uuid)->>'displayName','Meetup host','public host name is meetup identity');
select ok(not (public.get_chilling_host_profile(current_setting('test.profile_post')::uuid) ?| array['preferences','promptOne','promptTwo']),'v2 public host omits prompts and preferences');
select set_config('storage.operation','storage.object.get_authenticated',true);
select is((select count(*)::integer from storage.objects where bucket_id='meetup-profiles'),2,'applicant reads own photo and explicitly public host photo only');
reset role;
select set_config('request.jwt.claims','{"sub":"51900000-0000-4000-8000-000000000004","role":"authenticated"}',true);
set local role authenticated;
select is(public.get_chilling_application(current_setting('test.profile_request')::uuid),null::jsonb,'stranger denied application snapshot');
select is(public.get_chilling_member_profile(current_setting('test.profile_post')::uuid,'51900000-0000-4000-8000-000000000002'),null::jsonb,'stranger denied member identity');
select is(public.get_chilling_roster(current_setting('test.profile_post')::uuid),'[]'::jsonb,'stranger denied roster');
select is((select count(*)::integer from storage.objects where bucket_id='meetup-profiles'),1,'guessed private applicant photo denied');
select set_config('storage.operation','storage.object.create_signed_url',true);
select is((select count(*)::integer from storage.objects where bucket_id='meetup-profiles'),0,'signed URL operation denied including public host photo');
select set_config('storage.operation','storage.object.get_authenticated',true);
reset role;
select set_config('request.jwt.claims','{"sub":"51900000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is(public.get_chilling_application(current_setting('test.profile_request')::uuid)->'profile'->>'displayName','Snapshot name','host sees application snapshot name');
select is(public.get_pending_chilling_requests()->0->'requester'->>'nickname','Snapshot name','pending inbox uses consented alias');
select ok(not (public.get_pending_chilling_requests()::text like '%General secret%' or public.get_pending_chilling_requests()::text like '%Private application answer%'),'pending inbox excludes general identity and answers');
reset role;
insert into public.reports(reporter_id,reported_user_id,target_type,target_id,reason_code)
 values('51900000-0000-4000-8000-000000000002','51900000-0000-4000-8000-000000000001','post',current_setting('test.profile_post')::uuid,'other');
set local role authenticated;
select is(public.get_chilling_application(current_setting('test.profile_request')::uuid),null::jsonb,'applicant reporting meetup revokes host private application read');
select is(public.get_pending_chilling_requests(),'[]'::jsonb,'applicant reporting meetup removes guarded pending identity');
reset role;
delete from public.reports where reporter_id='51900000-0000-4000-8000-000000000002';
set local role authenticated;

select is((select author_nickname from public.get_public_post(current_setting('test.profile_post')::uuid)),'Meetup host','post DTO uses published meetup name');
select is((select author_neighborhood from public.get_public_post(current_setting('test.profile_post')::uuid)),null::text,'post DTO suppresses general neighborhood');
select is((select count(*)::integer from public.get_public_author_posts(auth.uid())),0,'general community author page excludes meetup posts before page limit');
select is((select count(*)::integer from public.get_public_feed_page('vancouver',null,'General secret 1')),0,'legacy feed cannot link meetup through general nickname search');
select is((select count(*)::integer from public.get_public_feed_page_v2('vancouver',null,'General secret 1')),0,'v2 feed cannot link meetup through general nickname search');
select is((select count(*)::integer from public.get_public_feed_page_v2('vancouver',null,'Synthetic profile')),1,'normal meetup title search remains functional');

select is((select other_nickname from public.get_conversation_previews() where group_post_id=current_setting('test.profile_post')::uuid),'Meetup host','group inbox uses meetup name');
select is((select room_preview->>'hostDisplayName' from public.posts where id=current_setting('test.profile_post')::uuid),'Meetup host','public metadata contains only published name');
select ok(not exists(select 1 from public.notifications where target_id=current_setting('test.profile_request')::uuid and body like '%General secret%'),'request notification body does not leak account nickname');
select is((select body from public.notifications where target_id=current_setting('test.profile_request')::uuid and kind='meetup_request'),'모임 참여 요청이 도착했어요. 한번 확인해 주세요.','request keeps the active copy variant without community identity');
select is((select route from public.notifications where target_id=current_setting('test.profile_request')::uuid and kind='meetup_request'),'/chat?requestId='||current_setting('test.profile_request'),'request notification still opens the exact application');

select is((select count(*)::integer from storage.objects where bucket_id='meetup-profiles'),2,'host reads active applicant photo');
select lives_ok($$select public.respond_meetup_request(current_setting('test.profile_request')::uuid,'approved')$$,'existing approval path preserved');
-- The service worker's opt-in group push preview must also avoid community identity.
reset role;
insert into auth.sessions(id,user_id,created_at) values('519fffff-0000-4000-8000-000000000003','51900000-0000-4000-8000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"51900000-0000-4000-8000-000000000001","role":"authenticated","session_id":"519fffff-0000-4000-8000-000000000003"}',true);
set local role authenticated;
select public.update_notification_preferences('{"push_enabled":true,"message_preview":true}');
select public.register_push_device('ExpoPushToken[meetupProfile123456]',auth.uid());
reset role;
select set_config('request.jwt.claims','{"sub":"51900000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select set_config('test.group_message',public.send_message((select id from public.conversations where group_post_id=current_setting('test.profile_post')::uuid),'A meetup message')::text,true);
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is((select body from public.claim_push_notifications('send',100) where category='messages' and user_id='51900000-0000-4000-8000-000000000001'),'Snapshot name: A meetup message','opt-in group push uses frozen meetup sender alias');
reset role;
select ok(exists(select 1 from public.safety_review_queue where target_type='message' and target_id=current_setting('test.group_message')::uuid),'group message remains covered by all-content safety monitoring');
select set_config('request.jwt.claims','{"sub":"51900000-0000-4000-8000-000000000001","role":"authenticated","session_id":"519fffff-0000-4000-8000-000000000003"}',true);
set local role authenticated;
select set_config('test.profile_session',public.create_meetup_session(current_setting('test.profile_post')::uuid,now()+interval '1 hour',now()+interval '2 hours')::text,true);
select is(public.get_meetup_sessions(current_setting('test.profile_post')::uuid)->'sessions'->0->'members'->1->>'nickname','Snapshot name','session roster uses meetup snapshot name');
select ok(public.get_meetup_sessions(current_setting('test.profile_post')::uuid)::text not like '%General secret%','session projection excludes general nicknames');
reset role;
insert into private.trust_reviews(kind,author_id,session_id,score,body,status,release_at)
 values('meetup','51900000-0000-4000-8000-000000000002',current_setting('test.profile_session')::uuid,8,'Public meetup review','published',now());
set local role authenticated;
select is(public.get_meetup_reviews(current_setting('test.profile_post')::uuid)->'reviews'->0->>'nickname','Snapshot name','review author uses meetup snapshot name');
select ok(public.get_meetup_reviews(current_setting('test.profile_post')::uuid)::text not like '%General secret%','review projection excludes general nicknames');
select lives_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"displayName":"Unpublished host edit"}')$$,'host edits live profile');
select is(public.get_chilling_host_profile(current_setting('test.profile_post')::uuid)->>'displayName','Meetup host','host publication stays frozen after private edit');
reset role;
select set_config('request.jwt.claims','{"sub":"51900000-0000-4000-8000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select public.save_chilling_profile('{"version":2,"displayName":"Private member","cityId":"vancouver","photoPaths":["51900000-0000-4000-8000-000000000003/1792380000000-aabbccdd.webp"],"publicPhotoPath":null,"intro":"Not shared","interests":["walk"],"promptOne":"Private one","promptTwo":"Private two","promptOneId":"meet","promptTwoId":"join","shareWithMembers":false,"preferences":{"activities":[],"availability":"","pace":"any"}}');
select set_config('test.member_request',public.request_chilling_join_v2(current_setting('test.profile_post')::uuid,'Member answer','chilling-v2',public.get_my_chilling_profile()->>'revision')::text,true);
reset role;
select set_config('request.jwt.claims','{"sub":"51900000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select public.respond_meetup_request(current_setting('test.member_request')::uuid,'approved');
reset role;
select set_config('request.jwt.claims','{"sub":"51900000-0000-4000-8000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is(public.get_chilling_member_profile(current_setting('test.profile_post')::uuid,'51900000-0000-4000-8000-000000000002')->>'displayName','Snapshot name','approved peer sees request-bound meetup name');
select ok(not (public.get_chilling_member_profile(current_setting('test.profile_post')::uuid,'51900000-0000-4000-8000-000000000002') ?| array['promptOne','promptTwo','preferences','answer']),'peer projection omits private fields');
select is((select count(*)::integer from storage.objects where bucket_id='meetup-profiles'),3,'approved member sees explicitly shared applicant photo');
select is(public.get_chilling_application(current_setting('test.profile_request')::uuid),null::jsonb,'approved peer cannot read private application answers');
reset role;
insert into public.blocks(blocker_id,blocked_id) values('51900000-0000-4000-8000-000000000002','51900000-0000-4000-8000-000000000001');
set local role authenticated;
select is(public.get_chilling_member_profile(current_setting('test.profile_post')::uuid,'51900000-0000-4000-8000-000000000002'),null::jsonb,'subject blocking host revokes peer profile sharing');
select is((select count(*)::integer from storage.objects where bucket_id='meetup-profiles'),2,'subject blocking host revokes peer photo sharing');
reset role;
delete from public.blocks where blocker_id='51900000-0000-4000-8000-000000000002';
insert into public.reports(reporter_id,reported_user_id,target_type,target_id,reason_code)
 values('51900000-0000-4000-8000-000000000002','51900000-0000-4000-8000-000000000001','post',current_setting('test.profile_post')::uuid,'other');
