select is(public.get_chilling_member_profile(current_setting('test.profile_post')::uuid,'51900000-0000-4000-8000-000000000002'),null::jsonb,'subject reporting meetup revokes peer profile sharing');
select is((select count(*)::integer from storage.objects where bucket_id='meetup-profiles'),2,'subject reporting meetup revokes peer photo sharing');
