select is(public.get_chilling_member_profile(current_setting('test.profile_post')::uuid,'51900000-0000-4000-8000-000000000003')->>'intro','','member without opt-in shares no introduction');
select is(public.get_chilling_member_profile(current_setting('test.profile_post')::uuid,'51900000-0000-4000-8000-000000000003')->>'cityId',null::text,'member without opt-in shares no city');
select is(public.get_chilling_member_profile(current_setting('test.profile_post')::uuid,'51900000-0000-4000-8000-000000000003')->'photoPaths','[]'::jsonb,'member without opt-in shares no photos');
