select set_config('storage.operation','storage.object.upload',true);
select lives_ok($$insert into storage.objects(bucket_id,name,owner_id,metadata) values('meetup-profiles','51900000-0000-4000-8000-000000000002/1792380000000-deadbeef.webp',auth.uid()::text,'{"size":1024,"mimetype":"image/webp"}')$$,'owner uploads immutable draft');
select lives_ok($$insert into storage.objects(bucket_id,name,owner_id,metadata) values('meetup-profiles','51900000-0000-4000-8000-000000000002/1792380000000-deadbeef.png',auth.uid()::text,'{"size":1024,"mimetype":"image/webp"}')$$,'upload RLS permits owner preflight before final binding');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"photoPaths":["51900000-0000-4000-8000-000000000002/1792380000000-deadbeef.png"]}')$$,'P0001','INVALID_CHILLING_PHOTO','saved-object MIME must match extension at binding');
select lives_ok($$insert into storage.objects(bucket_id,name,owner_id,metadata) values('meetup-profiles','51900000-0000-4000-8000-000000000002/1792380000000-feedbeef.webp',auth.uid()::text,'{"mimetype":"image/webp","contentLength":1024}')$$,'official upload preflight metadata does not require saved size');
select throws_ok($$select public.save_chilling_profile((public.get_my_chilling_profile()-'revision')||'{"photoPaths":["51900000-0000-4000-8000-000000000002/1792380000000-feedbeef.webp"]}')$$,'P0001','INVALID_CHILLING_PHOTO','preflight metadata cannot masquerade as a committed valid image');
reset role;
